def eulerian_num(n, m):
    @lru_cache(maxsize=None)
    def a(n, m):
        # Base cases
        if m < 0 or m >= n:
            return 0
        if m == 0:
            return 1

        # Recurrence relation: A(n,m) = (m+1)*A(n-1,m) + (n-m)*A(n-1,m-1)
        return (m + 1) * a(n - 1, m) + (n - m) * a(n - 1, m - 1)

    return a(n, m)

